cases h with k
cases k with
| zero k' => exact (or.intro (by { rw ← nat_mod_4_mul_4; simp [k']; exact zero_ne_one_iff; linarith }))
| succ k' =>
  let m_mod := m % 4
  let n_mod := n % 4
  let k_mod := k % 4
  have : k_mod = 1 := by { rw ← nat_mod_4_mul_4; simp [k']; exact zero_ne_one_iff; linarith }
  have : m_mod * n_mod ≡ 3 mod 4 := by { rw ← nat_mod_4_mul_4; simp [k_mod]; exact h }
  have : m_mod * n_mod ≡ 0 mod 4 ∨ m_mod * n_mod ≡ 1 mod 4 ∨ m_mod * n_mod ≡ 2 mod 4 := by { cases n_mod; cases m_mod; exact or.intro (or.intro (or.intro (by { simp [nat_mul_mod]; linarith })) (by { simp [nat_mul_mod]; linarith })) }
  have : m_mod * n_mod ≡ 3 mod 4 ⇒ m_mod * n_mod ≡ 1 mod 4 ∨ m_mod * n_mod ≡ 2 mod 4 := by { cases n_mod; cases m_mod; exact or.intro (or.intro (by { simp [nat_mul_mod]; linarith })) (by { simp [nat_mul_mod]; linarith }) }
  have : m_mod * n_mod ≡ 1 mod 4 ∨ m_mod * n_mod ≡ 2 mod 4 ⇒ m_mod * n_mod ≡ 0 mod 4 ∨ m_mod * n_mod ≡ 1 mod 4 ∨ m_mod * n_mod ≡ 2 mod 4 := by { exact or.elim (by { cases n_mod; cases m_mod; exact or.intro (or.intro (by { simp [nat_mul_mod]; linarith })) (by { simp [nat_mul_mod]; linarith }) }) }
  exact or.intro (by { cases n_mod; cases m_mod; exact or.intro (by { simp [nat_mul_mod]; linarith; rw ← nat_mod_4_mul_4; simp [k_mod]; exact (m_mod * n_mod ≡ 1 mod 4) }) (by { simp [nat_mul_mod]; linarith; rw ← nat_mod_4_mul_4; simp [k_mod]; exact (m_mod * n_mod ≡ 2 mod 4) }) })
